import{_ as r,c as a,o as t,ag as i}from"./chunks/framework.Sr95JMjc.js";const d=JSON.parse('{"title":"무료 할당량을 제공하는 Agentic IDE","description":"","frontmatter":{"title":"무료 할당량을 제공하는 Agentic IDE","date":"2025-12-08T21:00+09:00","tags":null},"headers":[],"relativePath":"posts/free-limits-agentic-ide.md","filePath":"posts/free-limits-agentic-ide.md","lastUpdated":1777590745000}'),o={name:"posts/free-limits-agentic-ide.md"};function n(l,e,s,c,h,g){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="무료-할당량을-제공하는-agentic-ide" tabindex="-1">무료 할당량을 제공하는 Agentic IDE <a class="header-anchor" href="#무료-할당량을-제공하는-agentic-ide" aria-label="Permalink to &quot;무료 할당량을 제공하는 Agentic IDE&quot;">​</a></h1><p>대표적인 코딩 에이전트를 지원하는 <a href="https://www.claude.com/product/claude-code" target="_blank" rel="noreferrer">Claude Code</a> 또는 <a href="https://cursor.com/" target="_blank" rel="noreferrer">Cursor</a> 는 무료 할당량을 지원하지 않아요. 조직에서 AI 코딩 에이전트에 대한 비용을 복지로 지원하지 않거나 AI 에 대한 비용이 부담스러운 개발자들을 위해 무료 할당량을 제공하는 에이전트 또는 에이전틱 IDE를 찾아보았어요.</p><h2 id="github-copilot" tabindex="-1">Github Copilot <a class="header-anchor" href="#github-copilot" aria-label="Permalink to &quot;Github Copilot&quot;">​</a></h2><p><a href="https://github.com/features/copilot?locale=ko-KR" target="_blank" rel="noreferrer">깃허브 코파일럿</a>은 Jetbrains IDE 또는 VSCode 와 같은 에디터에서 사용할 수 있도록 확장 플러그인을 지원하면서도 <mark>매월 50회의 에이전트 모드 및 채팅 요청이 가능한</mark> Free 요금제를 지원해요.</p><blockquote><p>Github Copilot 프리뷰 기능을 활성화하면 <a href="https://github.blog/changelog/2025-11-10-raptor-mini-is-rolling-out-in-public-preview-for-github-copilot/" target="_blank" rel="noreferrer">Raptor Mini</a> 모델을 사용해볼 수 있어요.</p></blockquote><h2 id="aws-kiro" tabindex="-1">AWS Kiro <a class="header-anchor" href="#aws-kiro" aria-label="Permalink to &quot;AWS Kiro&quot;">​</a></h2><p><a href="https://kiro.dev/" target="_blank" rel="noreferrer">Kiro</a>는 AWS에서 제공하는 VSCode 기반의 에이전틱 IDE로 <mark>월간 50 크레딧을 지원</mark>해요. 그리고 소셜 로그인 또는 Builder ID 를 사용하면 <a href="https://kiro.dev/pricing/" target="_blank" rel="noreferrer">최초 30일 간 이용할 수 있는 500 크레딧을 보너스로</a> 제공해줘요.</p><h2 id="gemini-cli" tabindex="-1">Gemini CLI <a class="header-anchor" href="#gemini-cli" aria-label="Permalink to &quot;Gemini CLI&quot;">​</a></h2><p><a href="https://geminicli.com/" target="_blank" rel="noreferrer">Gemini CLI</a>는 Gemini Code Assist 기준 내에서 <mark>일간 무료 할당량을 지원</mark>하고 있어요. 단, Google Antigravity 와 플랫폼 할당량을 공유하기 때문에 Google Antigravity 에서 할당량을 모두 소진했다면 일간 무료 할당량을 이용할 수 없어요.</p><h2 id="junie-pro" tabindex="-1">Junie Pro <a class="header-anchor" href="#junie-pro" aria-label="Permalink to &quot;Junie Pro&quot;">​</a></h2><p>JetBrains의 AI 코딩 에이전트인 Junie Pro 는 무료 요금제가 없지만 <mark>All Products Pack 구독인 경우</mark> AI Assistant 와 Junie 를 사용할 수 있는 AI Pro 요금제가 기본적으로 포함되어요. 현재 조직은 인텔리제이에 대한 라이센스 구독을 지원하고 있었기 때문에 AI Pro 요금제에서 제공해주는 <mark>월간 20 AI 크레딧</mark>을 사용할 수 있어요.</p><h2 id="google-antigravity" tabindex="-1">Google Antigravity <a class="header-anchor" href="#google-antigravity" aria-label="Permalink to &quot;Google Antigravity&quot;">​</a></h2><p>구글이 Windsurf 인력을 영입하고나서 <mark>VSCode 기반의 에이전틱 IDE로 공개</mark>했어요. 2025년 12월 5일 기준으로 <a href="https://blog.google/feed/new-antigravity-rate-limits-pro-ultra-subsribers/" target="_blank" rel="noreferrer">Google One 기반의 개발자 플랜이 적용되어</a> 기존 무료 요금제는 주간 할당량을 제공해요. <a href="https://one.google.com/ai" target="_blank" rel="noreferrer">Google One</a>의 Pro 요금제는 월 29,000원으로 <a href="https://cursor.com/pricing" target="_blank" rel="noreferrer">Cursor IDE</a>와 비교해서 많이 저렴하지만 개발자 플랜마저도 일부 할당량이 제공되고 <mark>매 5시간마다 초기화</mark> 됩니다.</p><blockquote><p>Gemini CLI 와 Gemini Code Assist 와 함께 무료 할당량이 공유됩니다.</p></blockquote><h2 id="끝으로" tabindex="-1">끝으로 <a class="header-anchor" href="#끝으로" aria-label="Permalink to &quot;끝으로&quot;">​</a></h2><p>이렇게 무료 할당량을 지원하는 AI 코딩 에이전트들을 살펴봤어요. AI 코딩 에이전트에서 제공해주는 무료 할당량은 프로젝트 코드 베이스에 따라 금방 소진되기 때문에 유료 요금제를 유도하는 걸 느낄 수 있을거에요. 그리고 Antigravity 는 구글 계정 기반이므로 조직 워크스페이스 계정과 개인 계정을 나누어서 사용할 수도 있겠네요.</p>',16)])])}const u=r(o,[["render",n]]);export{d as __pageData,u as default};
